/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isStringArray = require( '@stdlib/assert/is-string-array' ).primitives;
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'vega:title:set:subtitle' );


// MAIN //

/**
* Sets the subtitle text.
*
* ## Notes
*
* -   Providing `undefined` "unsets" the configured value.
*
* @private
* @param {(string|Array<string>|void)} value - input value
* @throws {TypeError} must be a string or an array of strings
* @returns {void}
*/
function set( value ) {
	var isVoid;
	var isStr;

	isStr = isString( value );
	if ( !isStr ) {
		isVoid = isUndefined( value );
		if ( !isVoid && !isStringArray( value ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` must be a string or an array of strings. Value: `%s`.', 'subtitle', value ) );
		}
	}
	if ( isVoid ) {
		if ( value === this._subtitle ) {
			return;
		}
		debug( 'Current value: ["%s"]. New value: %s.', join( this._subtitle, '", "' ), value );
		this._subtitle = value;
		this.emit( 'change' );
		return;
	}
	if ( isStr ) {
		value = [ value ];
	} else {
		value = copy( value );
	}
	if ( isUndefined( this._subtitle ) ) {
		debug( 'Current value: %s. New value: ["%s"].', this._subtitle, join( value, '", "' ) );
		this._subtitle = value;
		this.emit( 'change' );
		return;
	}
	if ( !hasEqualValues( value, this._subtitle ) ) {
		debug( 'Current value: ["%s"]. New value: ["%s"].', join( this._subtitle, '", "' ), join( value, '", "' ) );
		this._subtitle = value;
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
